INSERT INTO feature VALUES('effect-handlers','effects','Effect handlers','effect-rows','implemented','uncommon','mainstream languages','A handler interprets the operations of a computation, each clause receiving the continuation; a handle is a reset whose clauses receive the captured stack, and a return leaving a handler prints as written with its capability''s region. A clause whose continuation captured an obligation ends it exactly once, by resuming it or by `abandon(k)`, and an abandonment is refused inside an unwind. On the emitter, a clause that resumes its stack only from its tail position, or never names it, and whose body neither captures nor walks the frames, runs on the frames its operation left standing under a marker; any other clause receives them captured. A deep handler crosses to the kernel as the fold of its effect''s free model, one case per operation, and the kernel replays it.','core-checker core-sequent runtime-emitter surface-pretty','corpus/model/control/handler-exits.gandr corpus/model/control/capability-region.gandr corpus/pathological/control/capability-escape.gandr corpus/model/cancellation/abandoned.gandr corpus/pathological/cancellation/dropped.gandr corpus/pathological/cancellation/shielded.gandr corpus/model/drop/in-flight.gandr corpus/model/effects/exit.gandr corpus/model/effects/state-handler.gandr crates/runtime-emitter/tests/forms.rs','corpus/model/control/handler-exits.gandr',NULL);
